def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (everything after '+')
        if '+' in version:
            version_part, build_metadata = version.rsplit('+', 1)
        else:
            version_part = version

        # Split pre-release (everything after '-')
        if '-' in version_part:
            version_nums, prerelease = version_part.split('-', 1)
        else:
            version_nums = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_nums.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            # Convert to comparable form
            prerelease_tuple = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        version, original_index = item
        parsed = parse_version(version)
        major, minor, patch, prerelease_tuple = parsed

        # Version with prerelease sorts before version without
        # Use (0,) for versions with prerelease, (1,) for versions without
        if prerelease_tuple is not None:
            prerelease_sort = (0, prerelease_tuple)
        else:
            prerelease_sort = (1,)

        return (major, minor, patch, prerelease_sort, original_index)

    # Add original index to maintain stable sort
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for v, _ in sorted_versions]

